   for(let i=0;i<26;i++)rect(g,'rgba(255,255,255,'+(.25+.3*Math.sin(t*2+i*2))+')',((i*53+t*7)%W),hz+4+(i%7)*10,12,1.6);
   poly(g,'#9ab4d0',[[560-o*.4,hz],[580-o*.4,hz-26],[610-o*.4,hz-18],[640-o*.4,hz-34],[690-o*.4,hz]]);
   const vx=470-o;poly(g,'#7f9ac0',[[vx-250,hz],[vx-150,hz-60],[vx-60,hz-92],[vx-36,hz-96],[vx-8,hz-124],[vx+10,hz-126],[vx+44,hz-100],[vx+120,hz-78],[vx+230,hz-30],[vx+300,hz]]);
